changes[73] = 'На основном горизонте $h=1$ включение ESI снижает потерю относительно AR с 1,9598 до 1,8008, то есть на 8,1%. Добавление NFCI к этой европейской базе даёт дальнейшее снижение до 1,6343, или на 9,2%; добавление ANFCI — до 1,6365, или на 9,1%. В этом парном сравнении добавление каждого индекса уменьшает среднюю квантильную потерю на выбранных датах. Само по себе это ещё не устанавливает регулярно воспроизводимого преимущества. Средние потери двух расширений практически совпадают: потеря ANFCI выше потери NFCI лишь на 0,13%. Заметного различия по основной метрике на данном горизонте не наблюдается.'

f = pd.read_csv(P.parent / 'revision19/results/ANFCI_forecasts.csv')
pairs = [
    ('NFCI / AR + ESI', 'AR_ESI_NFCI', 'AR_ESI'),
    ('ANFCI / AR + ESI', 'AR_ESI_ANFCI', 'AR_ESI'),
    ('NFCI / HIST', 'AR_ESI_NFCI', 'HIST'),
    ('ANFCI / HIST', 'AR_ESI_ANFCI', 'HIST'),
    ('ANFCI / NFCI', 'AR_ESI_ANFCI', 'AR_ESI_NFCI'),
]
def dec(x):
    return f'{x:+.4f}'.replace('.', ',')
rows = []
diagnostics = []
for label, model, benchmark in pairs:
    row = [label]
    for h in [1, 4]:
        a = f.query("variant == 'expanding' and information == 'historical' and h == @h")
        w = a.pivot(index='origin', columns='model', values='loss')
        d = w[model] - w[benchmark]
        row += [dec(d.mean()), f'{int((d < 0).sum())}/{len(d)}']
        diagnostics.append(dict(model=model, benchmark=benchmark, h=h, n=len(d),
                                mean_difference=d.mean(), median_difference=d.median(),
                                wins=int((d < 0).sum()), ties=int((d == 0).sum()),
                                losses=int((d > 0).sum())))
    rows.append('| ' + ' | '.join(row) + ' |')
table = '\n'.join([
    '| Первая модель / ориентир | Средняя разность, $h=1$ | Дат с меньшей потерей, $h=1$ | Средняя разность, $h=4$ | Дат с меньшей потерей, $h=4$ |',
    '| --- | ---: | ---: | ---: | ---: |', *rows])
(P / 'evidence').mkdir(exist_ok=True)
pd.DataFrame(diagnostics).to_csv(P / 'evidence/forecast_comparison_breadth.csv', index=False)
