# Use consecutive note numbers in order of first citation, then sort definitions.
body, notes = text.split('## Источники и примечания к главе 2', 1)
numbers = list(dict.fromkeys(re.findall(r'\[\^(\d+)\]', body)))
mapping = {old: str(i + 1) for i, old in enumerate(numbers)}
assert len(mapping) == 25
text = re.sub(r'\[\^(\d+)\]', lambda m: '[^' + mapping[m[1]] + ']', text)
body, notes = text.split('## Источники и примечания к главе 2', 1)
note_parts = [p for p in notes.strip().split('\n\n') if p]
definitions = [p for p in note_parts if p.startswith('[^')]
end = [p for p in note_parts if not p.startswith('[^')]
definitions.sort(key=lambda p: int(re.match(r'\[\^(\d+)\]', p)[1]))
text = body + '## Источники и примечания к главе 2\n\n' + '\n\n'.join(definitions + end) + '\n'
(P / 'Chapter_2_Empirical_Analysis.md').write_text(text)
